/*
  Get the value of the reference variable/node output
  1. [string,string]
  2. [string,string][]
*/
export const getReferenceVariableValue = ({ value, nodesMap, variables }) => {
    if (!value)
        return value;
    const resoleValue = (value) => {
        const sourceNodeId = value[0];
        const outputId = value[1];
        if (sourceNodeId === VARIABLE_NODE_ID) {
            if (!outputId)
                return undefined;
            return variables[outputId];
        }
        // 避免 value 刚好就是二个元素的字符串数组
        const node = nodesMap instanceof Map ? nodesMap.get(sourceNodeId) : nodesMap[sourceNodeId];
        if (!node) {
            return value;
        }
        return node.outputs.find((output) => output.id === outputId)?.value;
    };
    // handle single reference value
    if (isValidReferenceValueFormat(value)) {
        return resoleValue(value);
    }
    // handle reference array
    if (Array.isArray(value) &&
        value.length > 0 &&
        value.every((item) => isValidReferenceValueFormat(item))) {
        return value
            .map((val) => {
            return resoleValue(val);
        })
            .flat()
            .filter((item) => item !== undefined);
    }
    return value;
};

export const formatVariableValByType = (val, valueType) => {
    if (!valueType)
        return val;
    if (val === undefined || val === null)
        return;
    // Value type check, If valueType invalid, return undefined
    if (valueType.startsWith('array') && !Array.isArray(val))
        return undefined;
    if (valueType === WorkflowIOValueTypeEnum.boolean)
        return Boolean(val);
    if (valueType === WorkflowIOValueTypeEnum.number)
        return Number(val);
    if (valueType === WorkflowIOValueTypeEnum.string) {
        return typeof val === 'object' ? JSON.stringify(val) : String(val);
    }
    if ([
        WorkflowIOValueTypeEnum.object,
        WorkflowIOValueTypeEnum.datasetQuote,
        WorkflowIOValueTypeEnum.selectApp,
        WorkflowIOValueTypeEnum.selectDataset
    ].includes(valueType) &&
        typeof val !== 'object')
        return undefined;
    return val;
};

