/* Update runtimeNode's outputs with interactive data from history */
export function rewriteNodeOutputByHistories(runtimeNodes, lastInteractive) {
    const interactive = lastInteractive;
    if (!interactive?.nodeOutputs) {
        return runtimeNodes;
    }
    return runtimeNodes.map((node) => {
        return {
            ...node,
            outputs: node.outputs.map((output) => {
                return {
                    ...output,
                    value: interactive?.nodeOutputs?.find((item) => item.nodeId === node.nodeId && item.key === output.key)?.value || output?.value
                };
            })
        };
    });
}
